describe('Video Player Resizing on Tablet Viewports', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.viewport('ipad-2'); // Set viewport to tablet size
    });

    it('should resize the video player proportionally on tablet viewports', () => {
        cy.get('.video-player') // Replace with the actual selector for the video player
            .should('be.visible')
            .then(($videoPlayer) => {
                const initialWidth = $videoPlayer.width();
                const initialHeight = $videoPlayer.height();

                // Simulate resizing the window
                cy.viewport('ipad-2'); // Ensure we are in tablet mode
                cy.wait(100); // Wait for any potential resizing animations

                const newWidth = $videoPlayer.width();
                const newHeight = $videoPlayer.height();

                // Check if the aspect ratio is maintained
                const aspectRatioBefore = initialWidth / initialHeight;
                const aspectRatioAfter = newWidth / newHeight;

                expect(aspectRatioBefore).to.equal(aspectRatioAfter);
            });
    });

    it('should not exceed maximum width on tablet viewports', () => {
        cy.get('.video-player') // Replace with the actual selector for the video player
            .should('be.visible')
            .then(($videoPlayer) => {
                const maxWidth = 768; // Example max width for tablet viewports
                cy.viewport('ipad-2'); // Ensure we are in tablet mode
                cy.wait(100); // Wait for any potential resizing animations

                const currentWidth = $videoPlayer.width();
                expect(currentWidth).to.be.lessThan(maxWidth);
            });
    });
});
